"""Author 78 verified line-completion exercises; retain the earlier 22 unchanged."""
import contextlib,io,json,pathlib,textwrap,collections
ROOT=pathlib.Path(__file__).resolve().parents[1]
rows=[];topic='types';week=1;level='Foundation'
def E(name,task,before,answer,after,hint,explanation,expected,tests='',indent=0):
    answers=[answer] if isinstance(answer,str) else answer
    before=textwrap.dedent(before).strip();after=textwrap.dedent(after).strip('\n')
    tests=textwrap.dedent(tests).strip()
    for solution in answers:
        code=before+'\n'+' '*indent+solution+'\n'+after
        namespace={};out=io.StringIO()
        with contextlib.redirect_stdout(out):exec(compile(code,'guided-example','exec'),namespace)
        assert out.getvalue().rstrip('\n')==expected,(name,out.getvalue(),expected)
        exec(compile(tests,'regression checks','exec'),namespace)
    rows.append(dict(id=f'code-add-{len(rows)+1:03}',topic=topic,week=week,level=level,name=name,task=task,before=before,after=after,answers=answers,indent=indent,hint=hint,explanation=explanation,referenceOutput=expected,tests=tests,source='Original Code lab practice'))
E('Parse an integer count','Convert raw to an integer and store it in count using int().','raw = "18"','count = int(raw)','print(count + 2)','Use the integer conversion function.','The text becomes the integer 18, allowing numeric addition rather than text concatenation.','20','assert count == 18 and type(count) is int')
E('Preserve a fractional reading','Convert raw to a float named flow, preserving the decimal part.','raw = "3.75"','flow = float(raw)','print(flow * 2)','Use float rather than truncating to an integer.','The conversion retains 3.75. Doubling it produces the floating-point result 7.5.','7.5','assert flow == 3.75 and type(flow) is float')
E('Keep a snapshot before rebinding','Bind previous to the current integer speed before speed is updated.','speed = 12','previous = speed','speed = 20\nprint(previous, speed)','Assignment binds the current value to another name.','The two names initially refer to the same immutable integer. Later rebinding speed leaves previous at 12.','12 20','assert previous == 12 and speed == 20')
E('Create a Boolean state flag','Set active using a strict comparison: pressure must exceed 100.','pressure = 105','active = pressure > 100','print(active)','A comparison expression produces a Boolean.','The comparison is true for 105. Storing the result gives a Boolean flag rather than a printed message.','True','assert active is True')
E('Report a numeric type name','Assign the readable type name of value to kind using type() and __name__.','value = 4.5','kind = type(value).__name__','print(kind)','Read __name__ from the result of type(value).','type(value) identifies the float class; its __name__ attribute is the text float.','float','assert kind == "float"')
topic='arithmetic'
E('Find rectangular area','Set area_m2 to width_m multiplied by height_m.','width_m = 0.3\nheight_m = 0.2',['area_m2 = width_m * height_m','area_m2 = height_m * width_m'],'print(f"{area_m2:.3f}")','Area is the product of the two lengths.','Multiplying metre lengths produces square metres. The expected area is 0.06 m².','0.060','assert abs(area_m2 - 0.06) < 1e-12')
E('Use a diameter in circular area','Set area using math.pi and the square of half the diameter.','import math\ndiameter = 0.4','area = math.pi * (diameter / 2)**2','print(f"{area:.4f}")','Radius is half of diameter; square the radius.','The area uses radius 0.2, giving pi times 0.04. Using the diameter directly would quadruple the result.','0.1257','assert math.isclose(area, 0.12566370614359174, abs_tol=1e-12)')
E('Convert cubic millimetres','Convert volume_mm3 to cubic metres in volume_m3 using 1000**3.','volume_mm3 = 5000','volume_m3 = volume_mm3 / 1000**3','print(f"{volume_m3:.9f}")','Cube the linear millimetre-to-metre conversion factor.','A cubic millimetre is one billionth of a cubic metre. The conversion must account for all three dimensions.','0.000005000','assert abs(volume_m3 - 5e-6) < 1e-15')
E('Compute kinetic energy','Set energy_j to 0.5 times mass_kg times speed_m_s squared.','mass_kg = 4\nspeed_m_s = 3','energy_j = 0.5 * mass_kg * speed_m_s**2','print(energy_j)','Exponentiation is ** in Python.','The squared speed is nine, giving 0.5 times four times nine = 18 joules.','18.0','assert energy_j == 18')
E('Separate full groups and leftovers','Use divmod(count, capacity) to assign groups and leftover together.','count = 29\ncapacity = 6','groups, leftover = divmod(count, capacity)','print(groups, leftover)','divmod returns the integer quotient and remainder as a pair.','Four full groups hold 24 items, leaving five. The check reconstructs the original count.','4 5','assert (groups,leftover) == (4,5)\nassert groups*capacity+leftover == count')
E('Calculate a percentage change','Set percent to 100 times the change divided by the initial value.','initial = 80\nfinal = 100','percent = 100 * (final - initial) / initial','print(percent)','Parenthesize final minus initial before dividing.','The change of 20 is one quarter of the initial 80, so the reported change is 25 percent.','25.0','assert percent == 25')
topic='strings';week=3
E('Normalize an instrument label','Use strip() followed by lower() to assign a normalized label to key.','raw = "  Pump-B  "','key = raw.strip().lower()','print(key)','Chain the two string methods in the stated order.','The result removes edge whitespace and normalizes case without changing the raw string.','pump-b','assert key == "pump-b"\nassert raw == "  Pump-B  "')
E('Extract a sensor prefix','Use a slice to keep the first three characters in prefix.','label = "SEN-204"','prefix = label[:3]','print(prefix)','The slice stop is excluded.','The positions zero through two spell SEN; slicing returns a new string.','SEN','assert prefix == "SEN"')
E('Read an identifier suffix','Use negative slicing to keep the last three characters in suffix.','label = "SEN-204"','suffix = label[-3:]','print(suffix)','Start three positions back from the end.','The suffix slice is independent of the prefix length and retains the final identifier characters.','204','assert suffix == "204"')
E('Split a delimited record','Split raw on semicolons into fields.','raw = "A;21.5;good"','fields = raw.split(";")','print(fields)','Use split with the explicit delimiter.','The three returned fields remain strings; numerical conversion is a separate step. ',"['A', '21.5', 'good']",'assert fields == ["A","21.5","good"]')
E('Join report headings','Join names using a comma and space, assigning the result to header.','names = ["time", "pressure", "flow"]','header = ", ".join(names)','print(header)','Call join on the separator string.','join inserts the separator between the labels without adding extra separators at either end.','time, pressure, flow','assert header == "time, pressure, flow"')
E('Count a pattern in a label','Assign the number of nonoverlapping AA occurrences to count.','text = "AABAA"','count = text.count("AA")','print(count)','Use the string count method.','The prefix and suffix each contribute one nonoverlapping AA occurrence.','2','assert count == 2')
topic='decisions';week=2
E('Require two operating constraints','Write the if header requiring temperature <= 80 and pressure <= 200, including the colon.','temperature = 75\npressure = 180','if temperature <= 80 and pressure <= 200:','    print("Allowed")\nelse:\n    print("Reject")','Both conditions must hold.','Conjunction makes acceptance depend on both limits, preventing one valid quantity from masking another violation.','Allowed','assert temperature <= 80 and pressure <= 200')
E('Reject an out-of-range reading','Write the if header for a value below 0 or above 100. Include the colon.','value = 120','if value < 0 or value > 100:','    print("Outside")\nelse:\n    print("Inside")','A violation on either side is sufficient.','The strict outside comparisons complement the inclusive valid interval from zero to one hundred.','Outside','assert not 0 <= value <= 100')
E('Choose a compact sign label','Set label with a conditional expression: negative if x < 0, otherwise nonnegative.','x = -4','label = "negative" if x < 0 else "nonnegative"','print(label)','The true expression comes before if in a conditional expression.','The condition selects one of two strings and assigns it without printing inside either branch.','negative','assert label == "negative"')
E('Handle an empty mean input','Complete the if header so mean calculation occurs only for a nonempty values list.','values = []','if values:','    print(sum(values)/len(values))\nelse:\n    print("No data")','An empty list has false truth value.','Testing the collection before division avoids an undefined mean and gives the empty case an explicit message.','No data','assert values == []')
E('Include a threshold in the upper band','Complete the elif header to classify score 60 and above as pass after the high branch.','score = 60\nif score >= 80:\n    print("high")','elif score >= 60:','    print("pass")\nelse:\n    print("retry")','The equality boundary belongs in pass.','The first branch fails at 60, and the inclusive elif includes the exact pass threshold.','pass','assert score == 60')
E('Check evenness with a remainder','Set even to the comparison that n divided by 2 has remainder zero.','n = 18','even = n % 2 == 0','print(even)','Use % to obtain the remainder and == to compare it.','Even integers are exact multiples of two, so their remainder on division by two is zero.','True','assert even is True')
topic='for'
E('Traverse odd positions','Write a for header giving i the values 1, 3 and 5 using range().','positions = []','for i in range(1, 6, 2):','    positions.append(i)\nprint(positions)','Supply start, excluded stop and step.','The stride of two selects three odd positions without including the stop value six.','[1, 3, 5]','assert positions == [1,3,5]')
E('Accumulate squared readings','Add x squared to total on the missing indented line.','values = [2, 3, 4]\ntotal = 0\nfor x in values:','total += x**2','print(total)','Square before adding to the retained accumulator.','The sum of squares is four plus nine plus sixteen, rather than the square of the sum.','29','assert total == 29',4)
E('Count strict exceedances','Increment count by one inside the condition.','values = [9, 10, 11, 15]\ncount = 0\nfor x in values:\n    if x > 10:','count += 1','print(count)','This missing line is inside both the loop and the if block.','Only eleven and fifteen satisfy the strict comparison; ten is a useful boundary fixture.','2','assert count == 2',8)
E('Stop at a sentinel','Insert break in the sentinel branch before the value is accumulated.','values = [4, 6, -1, 100]\ntotal = 0\nfor x in values:\n    if x == -1:','break','    total += x\nprint(total)','Exit the nearest loop at the marker.','The sentinel and later values do not enter the total, which therefore remains ten.','10','assert total == 10',8)
E('Retain indexed measurement pairs','Append the tuple (i, value) to indexed inside the loop.','values = [8, 12]\nindexed = []\nfor i, value in enumerate(values):','indexed.append((i, value))','print(indexed)','append accepts the complete tuple as one object.','The records preserve each value beside its zero-based source position.',"[(0, 8), (1, 12)]",'assert indexed == [(0,8),(1,12)]',4)
E('Iterate over matching columns','Complete the for header using zip(times, readings).','times = [0, 1]\nreadings = [20, 23]\npaired = []','for time, reading in zip(times, readings):','    paired.append((time, reading))\nprint(paired)','Unpack each pair produced by zip.','Pairing the equal-length inputs keeps each reading attached to its timestamp.',"[(0, 20), (1, 23)]",'assert paired == [(0,20),(1,23)]')
topic='while';week=3;level='Apply'
E('Consume a remaining budget','Subtract cost from remaining on each pass.','remaining = 10\ncost = 3\nsteps = 0\nwhile remaining >= cost:','remaining -= cost','    steps += 1\nprint(remaining, steps)','The loop condition ensures a full cost remains before an update.','Each subtraction consumes three units. Three updates leave one unit, which cannot fund another pass.','1 3','assert remaining == 1 and steps == 3',4)
E('Use a bounded convergence condition','Complete the while header requiring both error > tolerance and steps < max_steps.','error = 1.0\ntolerance = 0.1\nsteps = 0\nmax_steps = 8','while error > tolerance and steps < max_steps:','    error /= 2\n    steps += 1\nprint(error, steps)','Keep going only while accuracy is insufficient and the cap has not been reached.','Four halvings reach 0.0625, satisfying the tolerance before the step limit is used. The conditions serve distinct purposes.','0.0625 4','assert error <= tolerance and steps == 4')
E('Advance an index into a sequence','Increase index by one after each value enters total.','values = [3, 4, 5]\nindex = 0\ntotal = 0\nwhile index < len(values):\n    total += values[index]','index += 1','print(total)','The update must advance toward len(values).','Without advancing the index, the same value would be added indefinitely. The three distinct values sum to twelve.','12','assert total == 12 and index == 3',4)
E('Halve a search interval','Assign midpoint to high after the midpoint has been computed.','low, high = 0.0, 8.0\nwhile high-low > 1:\n    midpoint = (low+high)/2','high = midpoint','print(low, high)','This demonstration always retains the lower half.','Replacing the upper endpoint by the midpoint reduces the bracket widths from eight to four, two and one.','0.0 1.0','assert (low,high) == (0.0,1.0)',4)
E('Track a growing trial value','Multiply trial by two on each loop pass.','trial = 1\nwhile trial < 20:','trial *= 2','print(trial)','Use augmented multiplication.','The repeated doubling sequence reaches 32, the first power of two here that is at least twenty.','32','assert trial == 32',4)
E('Report whether a capped loop converged','Set converged by testing the final error against tolerance, inclusively.','error = 1.0\ntolerance = 0.01\nfor _ in range(3):\n    error /= 2','converged = error <= tolerance','print(converged)','Stopping a loop does not itself imply reaching its accuracy target.','Three updates leave error at 0.125, larger than 0.01, so the success flag is false.','False','assert error == 0.125 and converged is False')
topic='lists';week=5
E('Take an independent flat-list copy','Use copy() to create work from raw before changing work.','raw = [2, 4, 6]','work = raw.copy()','work[0] = 99\nprint(raw)','Assignment alone would create an alias.','The copied outer list allows replacing a scalar without overwriting the original measurement.','[2, 4, 6]','assert work == [99,4,6] and raw == [2,4,6]\nassert work is not raw')
E('Keep a middle slice','Assign values at indices 1 through 3 to middle using a slice.','values = [10, 20, 30, 40, 50]','middle = values[1:4]','print(middle)','The stop index is excluded.','The slice includes twenty, thirty and forty while leaving the source list intact.','[20, 30, 40]','assert middle == [20,30,40]')
E('Build calibrated readings','Use a list comprehension to add offset to each raw reading.','raw = [18, 20, 22]\noffset = 2','calibrated = [x + offset for x in raw]','print(calibrated)','The expression comes before the comprehension’s for clause.','The comprehension creates a new result sequence and preserves the original observations.','[20, 22, 24]','assert calibrated == [20,22,24] and raw == [18,20,22]')
E('Filter missing readings','Use a list comprehension retaining values that are not None.','readings = [2, None, 0, 5]','valid = [x for x in readings if x is not None]','print(valid)','Zero is a valid value here, so a truthiness filter would be wrong.','The explicit None check retains a real zero measurement while removing only the missing marker.','[2, 0, 5]','assert valid == [2,0,5]')
E('Create independent matrix rows','Use a comprehension to create two rows, each containing three zeros.','rows, cols = 2, 3','grid = [[0] * cols for _ in range(rows)]','grid[0][1] = 7\nprint(grid)','Create a new inner list on each pass.','Independent rows prevent a change in one row from appearing in another through aliasing.','[[0, 7, 0], [0, 0, 0]]','assert grid[1] == [0,0,0] and grid[0] is not grid[1]')
E('Unpack a measurement tuple','Unpack record into sensor, value and unit in that order.','record = ("A", 24, "C")','sensor, value, unit = record','print(sensor, value, unit)','There must be one target for each field.','Unpacking makes each field’s meaning visible without losing the original tuple.','A 24 C','assert (sensor,value,unit) == record')
E('Keep complete moving pairs','Use a comprehension to compute the mean of every adjacent pair.','values = [2, 4, 8, 10]','means = [(values[i] + values[i+1]) / 2 for i in range(len(values)-1)]','print(means)','There are n-1 adjacent pairs in a sequence of n values.','Each two-entry window has a valid start before the final index. All three complete pair means are retained.','[3.0, 6.0, 9.0]','assert means == [3.0,6.0,9.0]')
topic='dicts';week=6
E('Use an explicit default reading','Use get() to store -1 in value when key pressure is missing.','record = {"temperature": 22}','value = record.get("pressure", -1)','print(value)','Supply the missing-key default as the second get argument.','The task deliberately chooses -1 as a missing marker. get reads it without changing the dictionary or raising KeyError.','-1','assert value == -1 and "pressure" not in record')
E('Update a mapped measurement','Set the existing flow entry to 7 without changing the other entry.','record = {"flow": 3, "head": 8}','record["flow"] = 7','print(record)','Assign through the existing key.', 'Updating an existing dictionary key replaces its value without adding another mapping entry.',"{'flow': 7, 'head': 8}",'assert record == {"flow":7,"head":8} and len(record) == 2')
E('Read both keys and values','Complete the for header using items() to unpack each key and value.','readings = {"A": 2, "B": 5}\nrows = []','for key, value in readings.items():','    rows.append((key, value))\nprint(rows)','items supplies pairs; keys alone do not.','The loop retains the insertion order of this dictionary and associates each name with its stored value.',"[('A', 2), ('B', 5)]",'assert rows == [("A",2),("B",5)]')
E('Give each sensor a separate history','Use a dictionary comprehension with a new empty list per key.','sensors = ["A", "B"]','histories = {key: [] for key in sensors}','histories["A"].append(3)\nprint(histories)','Do not share one mutable default list between keys.','Evaluating [] separately for every key creates independent containers and prevents cross-sensor contamination.',"{'A': [3], 'B': []}",'assert histories["B"] == [] and histories["A"] is not histories["B"]')
E('Group values by their label','Append value to the list returned by groups.setdefault(label, []).','records = [("A", 2), ("B", 5), ("A", 4)]\ngroups = {}\nfor label, value in records:','groups.setdefault(label, []).append(value)','print(groups)','setdefault retains a new list only when the key is first encountered.','Each group keeps all of its values, allowing later aggregation without overwriting earlier samples.',"{'A': [2, 4], 'B': [5]}",'assert groups == {"A":[2,4],"B":[5]}',4)
E('Sum mapping values','Use sum() and values() to assign the total to total.','counts = {"Cu": 3, "Al": 2}','total = sum(counts.values())','print(total)','The values view contains counts rather than material names.','Summing the numeric counts gives five samples, while summing the keys would not implement the task.','5','assert total == 5')
E('Read a nested sensor field','Assign the temperature of sensor B to temperature.','sensors = {"A": {"temperature": 20}, "B": {"temperature": 25}}','temperature = sensors["B"]["temperature"]','print(temperature)','First select the sensor record, then its field.','The two key lookups follow the data structure’s levels instead of treating the inner field as a top-level key.','25','assert temperature == 25')
topic='functions';week=4
E('Return a geometric calculation','Return the rectangle perimeter using width and height.','def perimeter(width, height):','return 2 * (width + height)','print(perimeter(3, 5))','Add the two lengths before doubling.','Returning the calculation makes the result available to the caller and supports independent examples.','16','assert perimeter(0,5) == 10\nassert perimeter(2,2) == 8',4)
E('Return an empty-input policy','Return None when values is empty before the existing mean calculation.','def mean(values):\n    if not values:','return None','    return sum(values)/len(values)\nprint(mean([]), mean([2, 6]))','Exit the function from the empty branch.','The early return prevents division by zero and implements the explicitly stated missing-result policy.','None 4.0','assert mean([5]) == 5\nassert mean([]) is None',8)
E('Define a default scale factor','Write the def header for scale(value, factor=2), including the colon.','','def scale(value, factor=2):','    return value*factor\nprint(scale(4), scale(4, 3))','A default argument uses = in the parameter list.','The omitted factor uses two, while an explicitly supplied factor overrides that default for one call.','8 12','assert scale(0) == 0\nassert scale(-2,3) == -6')
E('Call with named arguments','Call ratio with numerator 10 and denominator 4 using those keyword names; assign result.','def ratio(numerator, denominator):\n    return numerator/denominator','result = ratio(numerator=10, denominator=4)','print(result)','Use the definition’s parameter names as keywords.','Named arguments make the intended numerator and denominator explicit even in a longer calling context.','2.5','assert result == 2.5')
E('Decompose a formula with a helper','Return square(x)+square(y) inside sum_of_squares.','def square(x):\n    return x*x\ndef sum_of_squares(x, y):','return square(x) + square(y)','print(sum_of_squares(3, 4))','Call the helper separately for each component.','The helper owns the squaring operation, while the outer function combines its two results.','25','assert sum_of_squares(0,2) == 4\nassert sum_of_squares(-3,4) == 25',4)
E('Pass an operation to a general helper','Inside apply, return function(value).','def apply(function, value):','return function(value)','def cube(x):\n    return x**3\nprint(apply(cube, 3))','The parameter is a callable supplied by the caller.','The general helper can use different operations without rewriting its control flow. This call applies cube to three.','27','assert apply(abs,-4) == 4',4)
E('Return a fresh transformed sequence','Return a comprehension adding 1 to each entry, without mutating values.','def shifted(values):','return [x + 1 for x in values]','raw = [2, 4]\nprint(shifted(raw), raw)','Construct a new list as the return value.','The operation derives new data and leaves the input sequence available for later analysis.','[3, 5] [2, 4]','assert shifted([]) == []\nassert raw == [2,4]',4)
topic='recursion';week=6;level='Challenge'
E('Count list entries recursively','Return 1 plus the recursive length of the tail.','def length(values):\n    if not values:\n        return 0','return 1 + length(values[1:])','print(length([3, 5, 7, 9]))','Each nonempty list contributes one head entry.','The tail slice reduces the input size until the empty-list base case contributes zero.','4','assert length([]) == 0\nassert length([8]) == 1',4)
E('Raise to a nonnegative integer power','For nonnegative n, return x times power(x, n-1).','def power(x, n):\n    if n == 0:\n        return 1','return x * power(x, n - 1)','print(power(2, 5))','Reduce the exponent by one, preserving the base.','The product unwinds from the exponent-zero identity one. The declared domain excludes negative exponents.','32','assert power(7,0) == 1\nassert power(-2,3) == -8',4)
E('Sum the digits of a nonnegative integer','Return the final digit plus the recursive digit sum of n//10.','def digit_sum(n):\n    if n < 10:\n        return n','return n % 10 + digit_sum(n // 10)','print(digit_sum(407))','% 10 extracts a digit; // 10 removes it.','Integer division shortens a nonnegative decimal representation, and the remainder supplies its last digit.','11','assert digit_sum(0) == 0\nassert digit_sum(123) == 6',4)
E('Reverse a string recursively','Return the reversed tail followed by the first character.','def reverse(text):\n    if len(text) <= 1:\n        return text','return reverse(text[1:]) + text[0]','print(reverse("pump"))','The first character belongs at the end of the returned result.','The base case protects indexing on an empty input; the recursive call shortens the string before concatenation.','pmup','assert reverse("") == ""\nassert reverse("A") == "A"\nassert reverse("ab") == "ba"',4)
E('Apply Euclid’s recursive step','For nonnegative a and b, return gcd(b, a%b) after the zero-b base case.','def gcd(a, b):\n    if b == 0:\n        return a','return gcd(b, a % b)','print(gcd(48, 18))','The remainder replaces the second argument.','Euclid’s identity preserves the common divisors while a smaller remainder leads toward the base case.','6','assert gcd(9,0) == 9\nassert gcd(7,5) == 1',4)
topic='engineering';week=1;level='Apply'
E('Convert a pressure report to kilopascals','Assign pressure_kpa by dividing pressure_pa by 1000.','pressure_pa = 245000','pressure_kpa = pressure_pa / 1000','print(pressure_kpa)','A kilopascal contains one thousand pascals.','The conversion changes the numeric scale while retaining the same physical pressure.','245.0','assert pressure_kpa == 245')
E('Compute ideal heating energy','Assign energy_j as mass_kg times heat_capacity times rise_k.','mass_kg = 2\nheat_capacity = 4200\nrise_k = 5','energy_j = mass_kg * heat_capacity * rise_k','print(energy_j)','Use Q = m c delta T under the stated ideal constant-capacity model.','The units multiply to joules. The example assumes uniform temperature and no heat loss.','42000','assert energy_j == 42000')
week=2
E('Accumulate energy from power intervals','Inside the loop, add power*dt to energy_j.','powers_w = [20, 30, 10]\ndt = 2\nenergy_j = 0\nfor power in powers_w:','energy_j += power * dt','print(energy_j)','Each interval contributes watts times seconds.','The common two-second intervals contribute forty, sixty and twenty joules, giving a total of 120.','120','assert energy_j == 120',4)
week=3
E('Measure a square-root residual','Assign residual as the absolute difference between guess squared and target.','target = 10\nguess = 3.2','residual = abs(guess**2 - target)','print(f"{residual:.2f}")','Use magnitude so negative and positive deviations are treated equally.','The residual compares the equation’s left and right sides, rather than the unknown root directly. It is approximately 0.24 here.','0.24','assert abs(residual-0.24) < 1e-12')
week=5
E('Find the largest absolute deviation','Use max() with a generator of abs(x-reference) to assign worst.','reference = 20\nreadings = [17, 21, 25]','worst = max(abs(x - reference) for x in readings)','print(worst)','Convert each signed departure into a magnitude before taking the maximum.','The deviations have magnitudes three, one and five. Taking their maximum prevents sign cancellation.','5','assert worst == 5')
topic='testing';week=7
E('Reject nonfinite parsed values','Write the if header raising the existing error for a value that is not finite.','import math\ndef parse(raw):\n    value = float(raw)','    if not math.isfinite(value):','        raise ValueError("nonfinite")\n    return value\ntry:\n    parse("nan")\nexcept ValueError:\n    print("Rejected")','Use not with math.isfinite(value).','NaN and infinity can parse successfully as floats. The explicit domain check rejects them before they enter downstream calculations.','Rejected','assert parse("2.5") == 2.5\nfor raw in ["nan","inf","-inf"]:\n    try:\n        parse(raw)\n    except ValueError:\n        pass\n    else:\n        raise AssertionError("nonfinite accepted")')
# Normalize the accepted missing line to its required logical indentation.
rows[-1]['answers']=['if not math.isfinite(value):'];rows[-1]['indent']=4
E('Check a floating-point known result','Complete an assert using math.isclose(result, 0.3, abs_tol=1e-12).','import math\nresult = 0.1 + 0.2','assert math.isclose(result, 0.3, abs_tol=1e-12)','print("Check passed")','Use an absolute tolerance instead of requiring exact bitwise equality.','The decimal values have small binary representation differences. The justified tolerance accepts this known result.','Check passed','assert abs(result-0.3) < 1e-12')
E('Catch an expected conversion failure','Write except ValueError: for the conversion attempt.','try:\n    value = int("oops")','except ValueError:','    value = None\nprint(value)','Catch the specific exception produced by invalid integer text.','The narrow handler establishes an explicit missing-result marker rather than hiding unrelated exception types.','None','assert value is None')
E('Preserve state in an empty-input check','Raise ValueError("empty") inside the existing empty-input branch.','def first(values):\n    if not values:','raise ValueError("empty")','    return values[0]\ntry:\n    first([])\nexcept ValueError:\n    print("Empty rejected")','The invalid-input branch should stop the calculation.','An explicit error follows the documented domain contract before the function indexes the empty sequence.','Empty rejected','assert first([7]) == 7\nassert first([0,1]) == 0',8)
topic='objects';week=8
E('Initialize independent object history','Inside __init__, assign a new empty list to self.history.','class Log:\n    def __init__(self):','self.history = []','    def add(self, value):\n        self.history.append(value)\na, b = Log(), Log()\na.add(3)\nprint(a.history, b.history)','Construct the list on the receiving instance.','Running initialization for each object creates separate mutable histories instead of a shared class-level list.','[3] []','assert a.history == [3]\nassert b.history == []\nassert a.history is not b.history',8)
E('Return a computed object query','Return self.value multiplied by self.gain from read().','class Sensor:\n    def __init__(self, value, gain):\n        self.value, self.gain = value, gain\n    def read(self):','return self.value * self.gain','s = Sensor(4, 3)\nprint(s.read())','Use instance attributes through self.','The method computes a result from the receiver’s stored state without changing that state.','12','assert Sensor(0,3).read() == 0\nassert Sensor(-2,5).read() == -10',8)
week=9
E('Initialize the base part of a subclass','Inside Child.__init__, call super().__init__(value) before setting gain.','class Base:\n    def __init__(self, value):\n        self.value = value\nclass Child(Base):\n    def __init__(self, value, gain):','super().__init__(value)','        self.gain = gain\nc = Child(7, 2)\nprint(c.value, c.gain)','An overriding initializer must delegate explicitly when base initialization is needed.','The base call establishes value on the same receiver; the child then adds its gain field.','7 2','assert isinstance(c,Base) and c.value == 7 and c.gain == 2',8)
E('Protect an internal flat list','Return self._values.copy() from values().','class History:\n    def __init__(self):\n        self._values = [2, 4]\n    def values(self):','return self._values.copy()','h = History()\nexternal = h.values()\nexternal.append(9)\nprint(h.values())','Return a new outer list instead of the stored one.','A defensive copy prevents caller-side append operations from modifying this flat numeric history through the returned value.','[2, 4]','assert h.values() == [2,4]\nassert external == [2,4,9]',8)
topic='algorithms';week=10
E('Count selected pair operations','Increment comparisons inside the nested loop.','n = 5\ncomparisons = 0\nfor i in range(n):\n    for j in range(i+1, n):','comparisons += 1','print(comparisons)','Count one operation for every unordered index pair.','The triangular loop visits four plus three plus two plus one pairs, for ten selected operations. This count is not a runtime measurement.','10','assert comparisons == 10',8)
week=11
E('Reuse an invariant total','Before the loop, assign total using sum(values).','values = [2, 3, 5]','total = sum(values)','fractions = []\nfor value in values:\n    fractions.append(value/total)\nprint(fractions)','The unchanged total need only be calculated once.','Preparing the invariant sum avoids repeated scans inside the normalization loop while preserving the complete output.','[0.2, 0.3, 0.5]','assert total == 10\nassert abs(sum(fractions)-1) < 1e-12')
week=12
E('Exclude a known-small midpoint','Update lo to mid+1 in the binary-search branch.','def search(values, target):\n    lo, hi = 0, len(values)-1\n    while lo <= hi:\n        mid = (lo+hi)//2\n        if values[mid] == target:\n            return mid\n        if values[mid] < target:','lo = mid + 1','        else:\n            hi = mid-1\n    return -1\nprint(search([2, 5, 9], 9))','The midpoint has already been ruled out.','Excluding the tested midpoint ensures strict interval progress, including two-entry search intervals. Input order is a precondition.','2','assert search([2,9],9) == 1\nassert search([],4) == -1\nassert search([2,5,9],7) == -1',12)
E('Sort whole records by a numeric field','Assign ordered using sorted(rows, key=lambda row: row[1]).','rows = [("A", 8), ("B", 3), ("C", 5)]','ordered = sorted(rows, key=lambda row: row[1])','print(ordered)','The key extracts a field without detaching it from the record.','The returned list ranks the numeric values while preserving the associated labels and leaving the original list unchanged.',"[('B', 3), ('C', 5), ('A', 8)]",'assert [r[0] for r in ordered] == ["B","C","A"]\nassert rows == [("A",8),("B",3),("C",5)]')
